using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers.Api;
[ApiController,Route("api/leads"),Authorize] public class LeadsApiController(ApplicationDbContext db,IAuditService audit):ControllerBase {
 [HttpGet]public async Task<IActionResult>Get(){var q=db.Leads.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))q=q.Where(x=>x.AssignedTo==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);return Ok(await q.Select(x=>new{x.LeadId,x.LeadCode,x.LeadName,x.Email,x.Phone,x.CompanyName,x.Source,x.Status,x.ExpectedValue}).ToListAsync());}
 [HttpPost]public async Task<IActionResult>Create(Lead input){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(!new[]{"New","Contacted","Qualified","Unqualified","Converted","Lost"}.Contains(input.Status))return BadRequest(new{message="Invalid lead status."});input.LeadId=0;input.LeadCode=$"LED-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}";input.AssignedTo=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;db.Add(input);await db.SaveChangesAsync();await audit.WriteAsync("Create","Lead",input.LeadId.ToString());return Created($"/api/leads/{input.LeadId}",new{input.LeadId,input.LeadCode,input.LeadName,input.Status});}
}
